#include <zephyr/kernel.h>
#include <zephyr/ztest.h>

#if defined(CONFIG_BBRAM_EMUL) && DT_NODE_HAS_STATUS(DT_NODELABEL(bbram0), okay)

#include <zephyr/drivers/bbram.h>
#include <zephyr/drivers/emul/bbram_emul.h>

#define BBRAM_NODE DT_NODELABEL(bbram0)

static const struct device *const bbram_dev = DEVICE_DT_GET(BBRAM_NODE);
static const struct emul *bbram_emul;

static void *bbram_emul_setup(void)
{
	zassert_true(device_is_ready(bbram_dev), "BBRAM device is not ready");
	bbram_emul = emul_get_binding(bbram_dev->name);
	return NULL;
}

static void before(void *fixture)
{
	ARG_UNUSED(fixture);

	/* Reset emulator to a known state */
	bbram_emul_set_invalid(bbram_emul, false);
	bbram_emul_set_standby_power_state(bbram_emul, true);
	bbram_emul_set_power_state(bbram_emul, true);

	/* And clear the memory */
	uint8_t val = 0;
	int rv = bbram_set_size(bbram_dev, 0);

	zassert_ok(rv, "Failed to reset size");
	for (int i = 0; i < CONFIG_BBRAM_EMUL_SIZE; ++i) {
		rv = bbram_write(bbram_dev, i, 1, &val);
		zassert_ok(rv, "Failed to clear byte %d", i);
	}
	rv = bbram_set_size(bbram_dev, CONFIG_BBRAM_EMUL_SIZE);
	zassert_ok(rv, "Failed to set size");
}

ZTEST(bbram_emul, test_get_size)
{
	size_t size;
	int rv;

	rv = bbram_get_size(bbram_dev, &size);
	zassert_ok(rv, "Failed to get size");
	zassert_equal(size, CONFIG_BBRAM_EMUL_SIZE, "Incorrect size");
}

ZTEST(bbram_emul, test_read_write)
{
	uint8_t buf[16];
	uint8_t read_buf[16];
	int rv;

	for (int i = 0; i < sizeof(buf); ++i) {
		buf[i] = i;
	}

	rv = bbram_write(bbram_dev, 0, sizeof(buf), buf);
	zassert_ok(rv, "Failed to write");

	rv = bbram_read(bbram_dev, 0, sizeof(read_buf), read_buf);
	zassert_ok(rv, "Failed to read");

	zassert_mem_equal(buf, read_buf, sizeof(buf), "Read data mismatch");
}

ZTEST(bbram_emul, test_out_of_bounds)
{
	uint8_t val = 0;
	int rv;

	rv = bbram_write(bbram_dev, CONFIG_BBRAM_EMUL_SIZE, 1, &val);
	zassert_equal(rv, -EINVAL, "Expected EINVAL for OOB write");

	rv = bbram_read(bbram_dev, CONFIG_BBRAM_EMUL_SIZE, 1, &val);
	zassert_equal(rv, -EINVAL, "Expected EINVAL for OOB read");

	rv = bbram_write(bbram_dev, 0, CONFIG_BBRAM_EMUL_SIZE + 1, &val);
	zassert_equal(rv, -EINVAL, "Expected EINVAL for OOB write");

	rv = bbram_read(bbram_dev, 0, CONFIG_BBRAM_EMUL_SIZE + 1, &val);
	zassert_equal(rv, -EINVAL, "Expected EINVAL for OOB read");
}

ZTEST(bbram_emul, test_invalid)
{
	size_t size;
	int rv;

	bbram_emul_set_invalid(bbram_emul, true);

	rv = bbram_get_size(bbram_dev, &size);
	zassert_equal(rv, -EIO, "Expected EIO for invalid data");

	bbram_emul_set_invalid(bbram_emul, false);

	rv = bbram_get_size(bbram_dev, &size);
	zassert_ok(rv, "Failed to get size after valid");
}

ZTEST(bbram_emul, test_power_off)
{
	size_t size;
	int rv;

	bbram_emul_set_power_state(bbram_emul, false);

	rv = bbram_get_size(bbram_dev, &size);
	zassert_equal(rv, -EIO, "Expected EIO for power off");

	bbram_emul_set_power_state(bbram_emul, true);

	rv = bbram_get_size(bbram_dev, &size);
	zassert_ok(rv, "Failed to get size after power on");
}

ZTEST(bbram_emul, test_standby_power_off)
{
	size_t size;
	int rv;

	bbram_emul_set_standby_power_state(bbram_emul, false);

	rv = bbram_get_size(bbram_dev, &size);
	zassert_equal(rv, -EIO, "Expected EIO for standby power off");

	bbram_emul_set_standby_power_state(bbram_emul, true);

	rv = bbram_get_size(bbram_dev, &size);
	zassert_ok(rv, "Failed to get size after standby power on");
}

ZTEST_SUITE(bbram_emul, NULL, bbram_emul_setup, before, NULL, NULL);

#else /* !(defined(CONFIG_BBRAM_EMUL) && DT_NODE_HAS_STATUS(DT_NODELABEL(bbram0), okay)) */

ZTEST(bbram_emul, test_skipped)
{
	ztest_test_skip();
}

ZTEST_SUITE(bbram_emul, NULL, NULL, NULL, NULL, NULL);

#endif
